-- All UUIDs/claims below belong only to the marked disposable synthetic DB.
select public.consent_test_assert(not has_schema_privilege('eps_oauth_consent_owner','auth','USAGE')and has_schema_privilege('postgres','auth','USAGE')and not has_schema_privilege('postgres','auth','USAGE WITH GRANT OPTION'),'managed Auth usage remains unavailable to coordinator and nondelegable by postgres');
select public.consent_test_assert((select proowner='postgres'::regrole and prosecdef and provolatile='s'and proconfig=array['search_path=""','TimeZone=UTC']::text[]from pg_proc where oid='eps.oauth_consent_browser_context()'::regprocedure),'context bridge has fixed postgres owner and empty search_path');
select public.consent_test_assert(has_function_privilege('eps_oauth_consent_owner','eps.oauth_consent_browser_context()','EXECUTE')and not has_function_privilege('authenticated','eps.oauth_consent_browser_context()','EXECUTE')and not has_function_privilege('anon','eps.oauth_consent_browser_context()','EXECUTE')and not has_function_privilege('service_role','eps.oauth_consent_browser_context()','EXECUTE'),'context bridge execute is private');
select public.consent_test_assert(not exists(select 1 from pg_auth_members where member='eps_oauth_consent_owner'::regrole),'coordinator inherits no role permissions');
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000001","role":"authenticated","aud":"authenticated","is_anonymous":false,"session_id":"20000000-0000-4000-8000-000000000001"}',true);
set local role eps_oauth_consent_owner;
select public.consent_test_assert(eps.oauth_consent_browser_context()=jsonb_build_object('principal_id','10000000-0000-4000-8000-000000000001'::uuid,'session_id','20000000-0000-4000-8000-000000000001'::uuid),'private context returns only verified ordinary principal and session');
select public.consent_test_assert((select count(*)>0 from eps.oauth_consent_claims),'own browser ledger rows remain visible through RLS without Auth usage');
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000001","role":"authenticated","aud":"authenticated","is_anonymous":false,"session_id":"20000000-0000-4000-8000-000000000002"}',true);
select public.consent_test_assert((select count(*)=0 from eps.oauth_consent_claims),'same principal other browser cannot read ledger rows');
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000002","role":"authenticated","aud":"authenticated","is_anonymous":false,"session_id":"20000000-0000-4000-8000-000000000003"}',true);
select public.consent_test_assert((select count(*)=0 from eps.oauth_consent_claims),'other principal cannot read ledger rows');
reset role;
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000001","role":"authenticated","aud":"authenticated","is_anonymous":true,"session_id":"20000000-0000-4000-8000-000000000001"}',true);
set local role authenticated;
select public.consent_test_reject($q$select public.eps_oauth_consent_claim(repeat('i',32),'https://studio.example.invalid/mcp','details','40000000-0000-4000-8000-000000000023')$q$,'anonymous browser denied');
reset role;
insert into auth.sessions values('20000000-0000-4000-8000-000000000004','10000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001',clock_timestamp()+interval'1 hour');
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000001","role":"authenticated","aud":"authenticated","is_anonymous":false,"session_id":"20000000-0000-4000-8000-000000000004"}',true);
set local role authenticated;
select public.consent_test_reject($q$select public.eps_oauth_consent_claim(repeat('i',32),'https://studio.example.invalid/mcp','details','40000000-0000-4000-8000-000000000024')$q$,'native OAuth session denied even without client_id claim');
reset role;delete from auth.sessions where id='20000000-0000-4000-8000-000000000002';
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000001","role":"authenticated","aud":"authenticated","is_anonymous":false,"session_id":"20000000-0000-4000-8000-000000000002"}',true);
set local role authenticated;
select public.consent_test_reject($q$select public.eps_oauth_consent_claim(repeat('i',32),'https://studio.example.invalid/mcp','details','40000000-0000-4000-8000-000000000025')$q$,'revoked browser session denied');
reset role;
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000001","role":"authenticated","aud":"authenticated","is_anonymous":false,"session_id":"20000000-0000-4000-8000-000000000001"}',true);
set local role authenticated;
insert into consent_test_values values('context-details',public.eps_oauth_consent_claim(repeat('i',32),'https://studio.example.invalid/mcp','details','40000000-0000-4000-8000-000000000026'));
reset role;update auth.oauth_authorizations set user_id='10000000-0000-4000-8000-000000000001'where authorization_id=repeat('i',32);set local role authenticated;
select public.eps_oauth_consent_finish(repeat('i',32),'https://studio.example.invalid/mcp',(select(value->>'claim_id')::uuid from consent_test_values where name='context-details'),'consent_ready');
insert into consent_test_values values('context-decision',public.eps_oauth_consent_claim(repeat('i',32),'https://studio.example.invalid/mcp','approve','40000000-0000-4000-8000-000000000027'));
select public.consent_test_reject($q$select public.eps_oauth_consent_finish(repeat('i',32),'https://studio.example.invalid/mcp',(select(value->>'claim_id')::uuid from consent_test_values where name='context-decision'),'consent_ready')$q$,'decision claim cannot be reset into consent_ready');
reset role;
select jsonb_build_object('result','passed','scope','synthetic-context-with-auth-usage-false','cloud_called',false,'provider_called',false)as context_local_proof;
